entries[269992] = { ["name"] = "Sharpened Arcanite Warglaive", ["text"] = "Heirloom Upgrade Level: 0/0\nBinds to Warband\nOne-Hand Warglaive\n8 - 13 Damage Speed 2.60\n(4.0 damage per second)\n+17 Intellect\n+4 [Agility or Intellect]\n+5 Stamina\n+ 4 Haste\n+ 3 Mastery\nRequires level 1 to 29 ( 29)\n\nVendor:\nEstelle Gendry\nZone:\nOrgrimmar - Gates of Orgrimmar\n\nVendor:\nKrom Stoutarm\nZone:\nIronforge - Hall of Explorers" }
entries[269994] = { ["name"] = "Griftah's Token of Appreciation", ["text"] = "Binds when picked up\n\"Griftah may generously give one of these as a reward for completing an endeavor task, depending on it's difficulty. Trade it with Griftah in your Neighborhood for exciting (or not) prizes.\"" }
entries[269999] = { ["name"] = "Overloaded Manaling", ["text"] = "Unique\nUse: Teaches you how to summon this companion.\n\nRight Click to summon and dismiss the Overloaded Manaling.\nRequires level 1 to 90 ( 90)" }
entries[270041] = { ["name"] = "Void-Touched Snapdragon", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"The snapdragon is a resilient creature and loyal by nature. This has made them preferred companions of the naga. However, their latest ritual has made this snapdragon ready for a new home.\"\nRitual Site:\nDaggerspine Point" }
entries[270058] = { ["name"] = "Rope Lynx Harness", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon the Void-Corrupted Lynx. This mount changes depending on your Riding skill and location.\n\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"The Eversong lynxes are known for their curiosity and this one especially. Sneaking into supply stores, and treasure boxes around ritual sites has changed it forever. Anyone who manages to leash it will have a feisty mount on their hands.\"\nRitual Sites:\nTreasure and Rare Spoils" }
entries[270061] = { ["name"] = "Void-Bathed Snapdragon", ["text"] = "Binds when picked up\nUse: Teaches you how to summon this companion.\n\nRight Click to summon and dismiss Void-Bathed Snapdragon.\nRequires level 1 to 90 ( 90)" }
entries[270062] = { ["name"] = "Void-Touched Chick", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to summon and dismiss this companion.\n\nRight Click to summon and dismiss this companion.\nRequires level 1 to 90 ( 90)" }
entries[270063] = { ["name"] = "Void-Touched Lynx Kitten", ["text"] = "Binds when picked up\nUse: Teaches you how to summon this companion.\n\nRight Click to summon and dismiss this companion.\nRequires level 1 to 90 ( 90)" }
entries[270160] = { ["name"] = "First Mate's Shellward", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+61 [Agility or Strength]\nUse: Deploy the Shellward to absorb up to 40% of incoming damage until 121947 damage has been prevented for up to 30 sec. The Shellward hardens while you are below 40% health, reducing damage by 80% instead.\n\nDeal 6067 Physical damage to melee attackers while the Shellward holds. (1 Min, 30 Sec Cooldown)\nSell Price:" }
entries[270161] = { ["name"] = "Fang of Umbral Malignance", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+61 Intellect\nEquip: Your harmful spells have a very high chance to befoul your target with Umbral Malignance, dealing ( 67 * 1 ) Shadow damage every 3 sec for 1 min, stacking up to 30 times.\n\nUmbral Malignance bursts upon the target's death, dealing 300% of its remaining damage split between nearby enemies and applying Umbral Malignance.\nSell Price:" }
entries[270162] = { ["name"] = "Soulcoiler Ritual Vessel", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+61 Intellect\nUse: Call forth 5 Soulcoiler Cultist spirits over 2 sec and sacrifice their essence, each granting an ally a barrier reducing damage taken by 50% for 20 sec or until ( 76084 * 1 ) damage has been prevented.\n\nAllied deaths reduce this cooldown by 30 sec and immediately summon a Soulcoil Cultist spirit for sacrifice. (2 Min Cooldown)\nSell Price:" }
entries[270163] = { ["name"] = "Sszorak's Ferocity", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+61 Strength\nEquip: You have a high chance to follow up your attacks with Ravage, Mutilate, or Tempest based on the number of nearby enemies.\n\nYour killer instincts are honed, triggering this effect on your next attack upon defeating an enemy. May only occur once per 10 sec.\n\"Fight. Scream. Die.\"\nSell Price:" }
entries[270164] = { ["name"] = "Gebbo's Bottomless Bag", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+61 [Agility or Strength or Intellect]\nEquip: You have a chance to pull an artifact of questionable value out of the bag when casting spells and abilities, enhancing your secondary stats in various ways. There are probably no fish left in the bag, but it's hard to be sure. (750ms cooldown)\n\"Disgusting fish! How does this keep happening? I should have total control!\"\nSell Price:" }
entries[270165] = { ["name"] = "Keeper's Seething Core", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+61 [Agility or Strength]\nEquip: Your attacks have a high chance to grant you Focus of Ula'tek, increasing your Haste by 68 for 12 sec. Multiple applications may overlap.\n\nWhen two or more applications are active, your focus sharpens further to increase the effect by 20%.\n\"Curse of her venom find you.\"\nSell Price:" }
entries[270166] = { ["name"] = "Vashnik's Sanguine Rancor", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+61 Agility\nEquip: Your attacks have a very high chance to build sanguine rancor within you. After 15 times, the rancor erupts to scourge your target and all nearby enemies with crimson bile, dealing ( 25689 * 1 ) Shadow damage split between them. Damage increased by 30% per additional enemy, up to 150%.\n\nIf only one enemy is struck, the concentrated bile deals an additional ( 25689 * 25 / 100 * 1 ) Shadow damage over 3 sec.\n\"Crimson. Viscous. Delicious.\"\nSell Price:" }
entries[270167] = { ["name"] = "Wavecaller's Seastone", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 76 Haste\nEquip: Your spells have a high chance to call to the sea, granting Tidal Insight to increase your Intellect by 22 up to 6 times. After reaching its peak, your spells instead diminish Tidal Insight before beginning the cycle anew.\nSell Price:" }
entries[270168] = { ["name"] = "Font of Venomous Rage", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 76 Mastery\nUse: Channel a torrent of venomous rage over 2 sec, dealing ( 1 * 382673 ) Nature damage to your target and splattering all nearby enemies for ( 1 * 67345 ) Nature damage. Damage reduced beyond 8 targets. (4 Min Cooldown)\nSell Price:" }
entries[270169] = { ["name"] = "Hex Lord's Dooming Idol", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 76 Haste\nEquip: Your spells afflict you with Hex Lord's Doom, draining your Intellect by 1 up to 30 times. This effect may occur once every 6 sec. (6s cooldown)\n\nUse: Consume the power of Hex Lord's Doom, increasing your Intellect by 12 per stack for 30 sec. (30 Sec Cooldown)\nSell Price:" }
entries[270170] = { ["name"] = "Vexhul's Everflowing Gland", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+61 Intellect\nUse: Unleash a deluge of caustic venom, dealing ( 14629 * 1 / 0.200000003) Nature damage to your target. Damage increased by 1% for every 1% health the enemy has remaining.\n\nDefeat enemies to catalyze their essential fluids into additional venom, reducing this cooldown by 5 sec. (3 Min Cooldown)\nSell Price:" }
entries[270171] = { ["name"] = "Preternatural Antivenom", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 76 Critical Strike\nEquip: Your healing has a high chance to infuse the target with Preternatural Antivenom for 30 sec, healing your ally for 75% of any damage they take until 100248 health has been restored.\nSell Price:" }
entries[270173] = { ["name"] = "Zul'jin's Guillotine Technique", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+61 [Agility or Strength]\nEquip: You have a chance to follow up your attacks with Guillotine, hurling a massive axe in an arc at your target to deal ( 11142 * 1 ) Physical damage.\n\nDamage increased by 2% for every 1% health the target is missing.\n\"D'you want axe?\"\n\nBite of Zul'jan (0/3)\nZul'jin's Guillotine Technique\nAman'muso, Warlord's Vengeance\nMaze-roa, Warlord's Fury\n(2) Set : Perfect your Guillotine technique to ricochet to a second nearby enemy, dealing 100% of its damage and applying Venomfang to both targets.\nSell Price:" }
entries[270174] = { ["name"] = "Idol of the Howling Nexus", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 76 Mastery\nEquip: Dodging, parrying, or blocking has a high chance to call bolstering winds, increasing your Strength or Agility by 187 and Speed by 76 for 12 sec.\n\nIf you have not dodged, parried, or blocked for 15 sec, this effect is triggered immediately. May only occur once per 1 min.\nSell Price:" }
entries[270175] = { ["name"] = "Voracious Heart of Ula'tek", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 76 Critical Strike\nUse: Bite the heart and embrace the ravening hunger, gaining 150 Strength or Agility for 20 sec.\n\nWhile the hunger persists, gain a very high chance to devour a morsel of your target with every attack, dealing 3525 Physical damage and further increasing your Strength or Agility by 17 . (1 Min, 30 Sec Cooldown)\nSell Price:" }
entries[270191] = { ["name"] = "Lil'Kruul's Hilt", ["text"] = "Binds when picked up\nUse: Teaches you how to summon and dismiss this companion.\n\nRight-click to summon and dismiss Lil'Doomy.\nRequires level 1 to 90 ( 90)" }
