entries[271092] = { ["name"] = "Jan'thrazet, the Soul Fang", ["text"] = "Binds when picked up\nUnique-Equipped\nOne-Hand Dagger\n24 - 41 Damage Speed 1.80\n(18.1 damage per second)\n+188 Intellect\n+502 Stamina\n+ 54 Haste\nDurability 80 / 80\nEquip: Your spells have a chance to drain a nearby enemy's will, reducing their cast speed by 10% and increasing your Haste by 71 for 12 sec.\n\"Upon de bones of each Amani's sacrifice, our empire will rise.\"\nSell Price:" }
entries[271093] = { ["name"] = "Zatha'tek, Breath of Corruption", ["text"] = "Binds when picked up\nUnique-Equipped\nOne-Hand Dagger\n46 - 86 Damage Speed 1.80\n(36.7 damage per second)\n+32 Agility\n+502 Stamina\n+ 54 Critical Strike\nDurability 80 / 80\nEquip: Your attacks have a chance to inflict Breath of Corruption, dealing ( 3672 * 1 ) Nature damage and rending a Necrotic Tear that persists until death and increases the damage of this effect by 5%, up to 10 times.\n\"Bury dem. They must never know de price we paid.\"\nSell Price:" }
