entries[271341] = { ["name"] = "Galactic Voidsliver", ["text"] = "Midnight Season 1\nBinds when picked up\nUse: Combine five Galactic Voidslivers to create a Galactic Void Matrix capable of increasing the minimum item level of a Galactic Gladiator Weapon or Trinket to 298 in Arenas and Battlegrounds.\n\"A thin splinter of Void energy that thrums with barely contained aggression. More may be claimed from the defeated in Arenas and Battlegrounds.\"\nSell Price:" }
entries[271342] = { ["name"] = "Galactic Void Matrix", ["text"] = "Midnight Season 1\nBinds when picked up\nUse: Increase the minimum item level of a Galactic Gladiator Weapon or Trinket to 298 in Arenas and Battlegrounds.\n\"A tightly bound matrix of Galactic Void energy, stabilized through repeated conflict. Its power seeks worthy armaments.\"\nSell Price:" }
